            A_BRAKE_PIVOT,
            Transform {
                brake_rotation_deg: 7.5,
                ..Transform::default()
            },
            A_CENTER,
        );
        assert!((a_contact.x - A_BRAKE_PIVOT.x).abs() < 0.000_001);
        assert!((a_contact.y - A_BRAKE_PIVOT.y).abs() < 0.000_001);

        let x_contact = transform_x_point(
            Point::new(766.09, 282.99),
            XTransform {
                brake_rotation_deg: 7.0,
                ..XTransform::default()
            },
