        let emerged = p_counter_reveal_mask_path(1.0);
        assert_eq!(hidden[0], point_element(Point::new(BANNER_LEFT_X, 0.0)));
        assert_eq!(emerged[0], point_element(Point::new(0.0, 0.0)));
