const MOBILE_BREAKPOINT_WIDTH: f64 = 720.0;

impl Example {
    pub fn handle_mount(&mut self, ctx: &NodeContext) {
        self.sync_responsive_state(ctx);
    }

    pub fn handle_pre_render(&mut self, ctx: &NodeContext) {
        self.sync_responsive_state(ctx);
    }

